$('#admin-content').addEventListener('change',e=>{const select=e.target;if(select.name!=='theme_preset'||!select.value)return;const preset=THEME_PRESETS[select.value];const f=select.closest('form');if(!preset||!f)return;f.elements.title.value=preset.title;f.elements.occasion_type.value=preset.occasion_type;f.elements.description.value=preset.description;f.elements.accent_color.value=preset.accent_color;f.elements.background_color.value=preset.background_color;});

